import json
import urllib.request
import re


from config.settings import OLLAMA_MODEL

def clean_script(script: str) -> str:
    """Remove placeholder labels generated by the model."""
    patterns = [
        r"\[Practical Point \d+\]\s*",
        r"\[Example\]\s*",
        r"\[Insert.*?\]\s*",
    ]

    for pattern in patterns:
        script = re.sub(pattern, "", script, flags=re.IGNORECASE)

    return script.strip()


def generate_script(topic: str) -> str:
    """Generate a short-form video script using a local LLM."""
    prompt = f"""
You are a professional Indonesian short-form video scriptwriter.

CONTENT BRIEF:
{topic}

Requirements:
- Identify the exact topic, niche, audience, and content goal from the brief.
- Stay strictly on topic.
- Write natural, conversational Indonesian.
- Create one short hook directly related to the topic.
- Give exactly three practical points with different purposes.
- Point 1: Explain one specific task AI can perform.
- Point 2: Give a different real-world use case, not another version of point 1.
- Point 3: Give one actionable tip viewers can try themselves.
- Each point must describe a concrete action, not just claim that AI saves time.
- Do not repeat the same task, benefit, or example across points.
- Do not invent facts, statistics, quotes, or sources.
- End with one relevant CTA question.
- Keep the entire script between 60 and 100 words.
- Do not use markdown formatting or quotation marks.
- Return only the finished script in the required format.

Format:
HOOK: One relevant opening sentence.
BODY:
1. First key point and explanation.
2. Second key point and explanation.
3. Third key point and explanation.
CTA: One relevant closing sentence.
""".strip()

    payload = {
        "model": OLLAMA_MODEL,
        "prompt": prompt,
        "stream": False,
        "options": {
            "temperature": 0.3,
            "num_predict": 350,
        },
    }

    request = urllib.request.Request(
        "http://localhost:11434/api/generate",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    with urllib.request.urlopen(request, timeout=300) as response:
        result = json.loads(response.read().decode("utf-8"))

    return clean_script(result["response"].strip())




def revise_script(
    script: str,
    issues: list[str],
    brief: str = "",
) -> str:
    """Revise a script using the original content brief and quality feedback."""
    prompt = f"""
You are a concise Indonesian short-form video script editor.

CONTENT BRIEF:
{brief or "Use the topic and context from the original script."}

SCRIPT TO FIX:
{script}

QUALITY ISSUES:
{chr(10).join(issues)}

Instructions:
- Write in natural, concise Indonesian.
- Keep the script under 100 words.
- Preserve the original topic and intended audience.
- Make all three BODY points specific and practical.
- Each BODY point must teach a different action or use case.
- Do not repeat the same tool, task, benefit, or example across points.
- Avoid generic claims without a concrete example.
- Make every sentence directly relevant to the topic.
- Do not invent statistics or unsupported factual claims.
- Do not use markdown formatting.
- Return only the complete script in this format:
- The CTA must be one complete question with at least 6 words.
- Ensure HOOK, BODY, and CTA are complete.
- Rewrite the entire script, not just individual sections.

HOOK: One short sentence.
BODY:
1. One practical point.
2. One practical point.
3. One practical point.
CTA: One short question.
""".strip()

    payload = {
        "model": OLLAMA_MODEL,
        "prompt": prompt,
        "stream": False,
        "options": {
            "temperature": 0.1,
            "num_predict": 220,
        },
    }

    request = urllib.request.Request(
        "http://localhost:11434/api/generate",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=300) as response:
            result = json.loads(response.read().decode("utf-8"))

        return clean_script(result["response"].strip())

    except Exception as error:
        print(f"Warning: Revision failed: {error}")
        return script
